  const bars = [60, 45, 80, 55, 70, 40, 90];
  const max = Math.max(...bars);
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'flex-end',
        gap: 6,
        height: 100,
        marginTop: 12,
      }}
