        <div
          key={i}
          style={{
            flex: 1,
            height: "'`${(v / max) * 100}%`,
            background: '"'var(--g-color-base-brand)',
            borderRadius: '4px 4px 0 0',
            transition: 'height 0.3s ease',
            minWidth: 0,
          }}
        />
      ))}
    </div>
  );
}

export function ChartWidget({ id }: WidgetProps) {
  const label = CHART_LABELS[id] ?? 'Chart';

  return (
